python3 -c "
import json

with open('/root/DATA/products/CoachForce.json', 'r') as f:
    data = json.load(f)

# Search meeting transcripts for Market Research references
print('=== MEETING TRANSCRIPTS MENTIONING \"Market Research\" ===')
for i, meeting in enumerate(data['meeting_transcripts']):
    meeting_str = json.dumps(meeting)
    if 'market research' in meeting_str.lower() or 'market_research' in meeting_str.lower():
        print(f'\n--- Meeting Transcript #{i} ---')
        # Print metadata first
        meta = {k: v for k, v in meeting.items() if k not in ['transcript', 'Transcript']}
        print('Meeting metadata:', json.dumps(meta, indent=2))
        # Print transcript entries mentioning market research
        transcript = meeting.get('transcript', meeting.get('Transcript', []))
        if isinstance(transcript, list):
            for j, entry in enumerate(transcript):
                entry_str = json.dumps(entry)
                if 'market research' in entry_str.lower() or 'market_research' in entry_str.lower():
                    print(f'  Transcript entry #{j}:', json.dumps(entry, indent=4))
        elif isinstance(transcript, str):
            if 'market research' in transcript.lower():
                print('  Transcript (excerpt):', transcript[:1000])
        print()
" 2>&1
